// Use 30-minute window to catch batch-marked issues
const cutoff = new Date(Date.now() - 30 * 60 * 1000);
const fresh = $input.all().filter(i =>
  (i.json.status === 'approved' || i.json.status === 'completed' || i.json.status === 'released' || i.json.status === 'closed') &&
  new Date(i.json.updated_at) > cutoff
);
if (!fresh.length) return [];

// Deduplicate using workflow static data
const seen = $getWorkflowStaticData('global');
if (!seen.posted_ids) seen.posted_ids = [];

const unposted = fresh.filter(i => !seen.posted_ids.includes(i.json.id));
if (!unposted.length) return [];

seen.posted_ids = [...seen.posted_ids, ...unposted.map(i => i.json.id)];
if (seen.posted_ids.length > 500) seen.posted_ids = seen.posted_ids.slice(-500);

const RESOLUTION_LABELS = {
  code_change: 'Code Change',
  config_change: 'Config Change',
  no_action: 'No Action',
  duplicate: 'Duplicate',
  by_design: 'By Design',
  wont_fix: "Won't Fix",
  cancelled: 'Cancelled',
  canceled: 'Cancelled',
  not_reproducible: 'Not Reproducible',
  deferred: 'Deferred',
  completed: 'Completed',
};
const STATUS_EMOJI = { approved: '🚢', completed: '✅', closed: '✅', released: '🚀' };
const TYPE_EMOJI = { task: '📋', bug: '🐛', feature: '✨', epic: '🏔️', ops: '⚙️', research: '🔍' };

return unposted.map(i => {
  const t = i.json;
  const key = t.task_key || t.id?.slice(0,8) || '?';
  const statusEmoji = STATUS_EMOJI[t.status] || '✅';
  const typeEmoji = TYPE_EMOJI[t.type || 'task'] || '📋';
  const rawResType = t.resolution_type || t.status;
  const resType = RESOLUTION_LABELS[rawResType] ?? rawResType;
  const ts = new Date(t.updated_at).toLocaleString('en-US', {
    timeZone: 'America/New_York',
    month: 'short', day: 'numeric',
    hour: '2-digit', minute: '2-digit',
    hour12: true
  }) + ' EST';
  const text = `${statusEmoji} ${resType} | ${typeEmoji} **${key}** \u2014 ${t.title} at ${ts}`;
  return { json: { text } };
});

const items = $input.all();
if (!items.length) return [];
const lines = items.map(i => i.json.text).filter(Boolean);
if (!lines.length) return [];
const message = lines.join('\n');

const resp = await helpers.httpRequest({
  method: 'POST',
  url: 'https://discord.com/api/v10/channels/1487584901678104698/messages',
  headers: {
    'Authorization': 'Bot MTQ4NjA0MTQ3MTUwNDM1MTMxMw.GoiBGW.VS2nGK2X1LMjMjkOBL9NqrOVeUdZfbGo9HdAyo',
    'Content-Type': 'application/json',
    'User-Agent': 'DiscordBot (https://openclaw.ai, 1.0)'
  },
  body: JSON.stringify({ content: message })
});
return [{ json: { ok: true, count: lines.length, response: resp } }];
